import { useEffect, useRef, useState } from "react";
import type { HTMLAttributes, ReactNode, Ref } from "react";
import { Button as AriaButton } from "react-aria-components";
import { ChevronLeft, ChevronRight } from "./icons";
import { Badge } from "./Badge";
import { Button } from "./Button";
import "./Carousel.css";

// Carousel (Component, Category C) — a paged slide viewport with previous/next
// controls and position dots. No React Aria headless exists for carousels, so the
// paging is plain React state; the arrow controls borrow the Button Component and the
// dots borrow React Aria's own `Button` (the same primitive NumberField's stepper and
// SearchField's clear use). Owns its look (viewport radius, dots) via Cmp tokens.
//
// The viewport is a real SCROLL CONTAINER with CSS Scroll Snap, not a transformed
// track. That is the Category-C "borrow before you hand-roll" call: swipe, trackpad
// and wheel paging, kinetic scrolling, and the whole right-to-left axis come from the
// browser, so none of it is re-implemented here (a pointer-drag gesture layer would
// have been ~all of it by hand, and react-aria's `useMove` is not re-exported by
// react-aria-components — it would have meant a new direct dependency in every
// consumer's copy-paste). React drives it in one direction (index → scrollIntoView)
// and reads it back in the other (scrollend → index).
export interface CarouselProps extends Omit<HTMLAttributes<HTMLElement>, "className" | "aria-label"> {
  /** Slides to page through (one visible at a time). */
  slides: ReactNode[];
  /** Starting slide when uncontrolled. Ignored once `index` is supplied. */
  defaultIndex?: number;
  /** Current slide — pass with `onIndexChange` to control the carousel from outside
   *  (a deep link, a caption beside it, a thumbnail strip). Omit for uncontrolled.
   *  Controlled means controlled: a swipe is a *request*, and declining it snaps the
   *  scrollport back to `index`, the way React resets a controlled `<input>`. */
  index?: number;
  /** Called with the slide the carousel wants to move to. Fires in both modes. */
  onIndexChange?: (index: number) => void;
  /**
   * How the position is shown. `dots`: a row of picker dots under the slide, with the previous and
   * next controls at its two sides. `counter`: an `n/m` label over the slide's start corner and both
   * controls gathered in its end corner, so nothing covers a banner's content; for image banners.
   *
   * @default "dots"
   */
  indicator?: "dots" | "counter";
  /**
   * Show the previous/next controls only from this breakpoint step up (min-width, mobile-first),
   * the words and values of `Show`'s `from`: below it the controls are hidden and out of the tab
   * order, and swipe, the focusable viewport's arrow keys and the indicator still page it. For a
   * phone hero where the thumb swipes and the arrows would cover the banner. Omit to show them at
   * every width.
   */
  controlsFrom?: "medium" | "large";
  /** Accessible name for the carousel region — required (the `aria-roledescription`
   *  needs a name to be meaningful); no default is baked in (contract §7b). */
  "aria-label": string;
  /** Additional class. sd-carousel is always retained. */
  className?: string;
  /** Passed to the root section DOM element. */
  ref?: Ref<HTMLElement>;
}

export function Carousel({
  slides,
  defaultIndex = 0,
  index: controlledIndex,
  onIndexChange,
  indicator = "dots",
  controlsFrom,
  "aria-label": ariaLabel,
  className,
  ref,
  ...rest
}: CarouselProps) {
  /* Controlled/uncontrolled the RAC way (contract §5): `index` present → the consumer owns the
     value and internal state is ignored; absent → the carousel keeps its own, seeded from
     `defaultIndex`. `onIndexChange` fires either way, so a consumer can observe without taking
     ownership. This is the only component in the library holding its own `useState` — Tabs and
     SegmentedControl delegate to RAC and Pagination is fully controlled — so the pair has to be
     built by hand here. */
  const [uncontrolledIndex, setUncontrolledIndex] = useState(defaultIndex);
  const isControlled = controlledIndex !== undefined;
  const count = slides.length;
  /* Clamp on read, not on write: a controlled consumer can hand us anything, and `slides` can
     shrink under a stale index. Guard the empty case too — `% 0` is NaN. */
  const rawIndex = isControlled ? controlledIndex : uncontrolledIndex;
  const index = count > 0 ? Math.min(Math.max(rawIndex, 0), count - 1) : 0;

  const goTo = (next: number) => {
    if (count === 0) return;
    const wrapped = ((next % count) + count) % count;
    if (!isControlled) setUncontrolledIndex(wrapped);
    onIndexChange?.(wrapped);
  };

  const viewportRef = useRef<HTMLDivElement>(null);
  /* Whether the scrollport actually overflows, measured rather than inferred. Slide COUNT is the
     wrong proxy in both directions: one slide still scrolls if the consumer puts something wider
     than the box inside it (a scroll container with no keyboard access is the axe
     `scrollable-region-focusable` / WCAG 2.1.1 failure), while one slide that fits scrolls nowhere
     and a tab stop there is a focus ring on a control that cannot act. Observing the box and the
     track covers a resize and a content change alike. */
  const [isScrollable, setIsScrollable] = useState(false);

  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const measure = () => setIsScrollable(viewport.scrollWidth > viewport.clientWidth + 1);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(viewport);
    if (viewport.firstElementChild) observer.observe(viewport.firstElementChild);
    return () => observer.disconnect();
  }, [count]);

  /* Bumped on every settled swipe so the reconcile effect below is guaranteed to run — a
     controlled consumer that DECLINES the change re-renders nothing on its own, and without a
     render there is no chance to put the scrollport back. A counter (never an equal value) is
     what makes that reliable; reusing the slide index would let React bail out of the second
     identical swipe and leave the carousel stuck out of sync. */
  const [scrollSyncTick, setScrollSyncTick] = useState(0);

  /* Read the index back OUT of the scroll offset — the sync direction for a swipe/wheel.
     Direction-agnostic on purpose: when the inline axis runs right-to-left the browser
     reports a NEGATIVE `scrollLeft` (measured: -600 for slide 2 of a 300px viewport), so
     it is the MAGNITUDE that counts pages, never the sign. */
  const indexFromScroll = (viewport: HTMLDivElement) =>
    viewport.clientWidth > 0 ? Math.round(Math.abs(viewport.scrollLeft) / viewport.clientWidth) : 0;

  /* Drive the scrollport FROM the index, so an arrow press, a dot, `defaultIndex` and a
     controlled `index` all move the carousel exactly the way the user's own swipe does.
     `scrollIntoView` on the LOGICAL `inline` axis is what keeps this direction-agnostic —
     `scrollTo({ left })` would need a hand-computed RTL sign, which is the bug this
     replaced. `block: "nearest"` stops it from dragging the whole PAGE vertically to reveal
     the slide (measured: `window.scrollY` stays 0). Animation is not passed here: the
     viewport's `scroll-behavior` owns it in CSS, so `prefers-reduced-motion` is honored in
     the same place as every other motion rule. */
  /* Runs on `index` (an arrow, a dot, `defaultIndex`, a controlled prop) AND on `scrollSyncTick`
     (a settled swipe). The second dependency is what keeps a DECLINED controlled swipe from
     leaving the carousel lying: the scrollport would be showing a slide that `inert` +
     `aria-hidden` both declare absent, while a screen reader was handed the off-screen one —
     the visible and the announced slide would be different slides.
     It is deliberately NOT dep-free: reconciling after every render would let an unrelated
     parent re-render yank the scrollport mid-swipe. Both dependencies fire only once motion has
     stopped, so this never competes with the user's finger. */
  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    // Already showing it — an accepted swipe must not be scrolled a second time.
    if (indexFromScroll(viewport) === index) return;
    viewport.firstElementChild?.children[index]?.scrollIntoView({
      inline: "start",
      block: "nearest",
    });
  }, [index, scrollSyncTick]);

  /* `scrollend` (React 19 emits it natively) rather than a debounced `scroll`: it fires once,
     after snapping settles, so the index never flickers through the slides being passed. */
  const handleScrollEnd = () => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const next = indexFromScroll(viewport);
    if (next === index) return;
    goTo(next);
    // Ask for a reconcile pass; it is a no-op if the consumer takes the new index.
    if (isControlled) setScrollSyncTick((tick) => tick + 1);
  };

  return (
    <section
      {...rest}
      ref={ref}
      aria-label={ariaLabel}
      aria-roledescription="carousel"
      data-indicator={indicator}
      data-controls-from={controlsFrom}
      className={className ? `sd-carousel ${className}` : "sd-carousel"}
    >
      {/* `aria-live` on the slide container, per the APG carousel pattern: **polite** because this
          carousel never auto-rotates (the pattern reserves `off` for rotating ones), and
          `aria-atomic="false"` so only the slide that changed is announced, not the whole set.
          Without it, pressing Next moved the carousel silently — focus stays on the button, the
          visible slide swaps from "1 of 3" to "2 of 3", and a screen-reader user gets nothing back
          (measured: zero live regions on the page). */}
      <div
        className="sd-carousel__viewport"
        ref={viewportRef}
        onScrollEnd={handleScrollEnd}
        /* The scrollport must be operable by keyboard as well as by swipe. Browsers make a
           scroll container focusable on their own, but only once it has no focusable content
           — and every off-screen slide here is `inert` — so the tab stop is declared rather
           than inferred (it is also what axe's `scrollable-region-focusable` looks for).
           With it, the arrow keys page the carousel for free, from the browser.
           Gated on real overflow (see `isScrollable`), so it is present exactly when there is
           something to scroll — never a dead focus ring, never an unreachable scroll region. */
        tabIndex={isScrollable ? 0 : undefined}
        aria-live="polite"
        aria-atomic="false"
      >
        <div className="sd-carousel__track">
          {slides.map((slide, i) => (
            <div
              key={i}
              className="sd-carousel__slide"
              role="group"
              aria-roledescription="slide"
              aria-label={`${i + 1} of ${count}`}
              aria-hidden={i !== index || undefined}
              /* `inert` alongside `aria-hidden`, never `aria-hidden` alone. The off-screen slides are
                 still rendered and still `visibility: visible` — only translated out of the viewport —
                 so anything focusable inside them stays in the tab order. A focusable element inside
                 an `aria-hidden` subtree is the `aria-hidden-focus` violation: a keyboard user tabs
                 into a control that screen readers have been told does not exist. `inert` removes it
                 from focus and from the a11y tree together, which is the pair this needs. */
              inert={i !== index || undefined}
            >
              {slide}
            </div>
          ))}
        </div>
      </div>

      {count > 1 && indicator === "counter" && (
        <>
          {/* The slide group already names its position ("2 of 6") to assistive tech, so the visible
              label is not read a second time. */}
          <Badge variant="overlay" aria-hidden className="sd-carousel__counter">{`${index + 1}/${count}`}</Badge>
          <div className="sd-carousel__controls">
            <Button variant="outline" size="small" isIconOnly className="sd-carousel__step" aria-label="Previous slide" onPress={() => goTo(index - 1)}>
              <ChevronLeft aria-hidden size="1em" />
            </Button>
            <Button variant="outline" size="small" isIconOnly className="sd-carousel__step" aria-label="Next slide" onPress={() => goTo(index + 1)}>
              <ChevronRight aria-hidden size="1em" />
            </Button>
          </div>
        </>
      )}

      {count > 1 && indicator === "dots" && (
        <>
          <Button
            variant="outline"
            size="small"
            isIconOnly
            className="sd-carousel__prev"
            aria-label="Previous slide"
            onPress={() => goTo(index - 1)}
          >
            <ChevronLeft aria-hidden size="1em" />
          </Button>
          <Button
            variant="outline"
            size="small"
            isIconOnly
            className="sd-carousel__next"
            aria-label="Next slide"
            onPress={() => goTo(index + 1)}
          >
            <ChevronRight aria-hidden size="1em" />
          </Button>

          <div className="sd-carousel__dots" role="group" aria-label="Choose slide">
            {slides.map((_, i) => (
              /* React Aria's own Button, not a bare <button>: the dot is an interactive
                 surface, so its hover/pressed/focus feedback has to come from the RAC-emitted
                 `data-*` attributes the rest of the library styles against (contract §6.3), and
                 the press handling (touch, pointer-cancel, Space/Enter) is behavior we borrow
                 rather than re-derive (category C — assemble from React Aria first). It is the
                 headless primitive, not the Sando `Button` Component: a dot paints nothing that
                 Button's variants describe. */
              <AriaButton
                key={i}
                className="sd-carousel__dot"
                data-selected={i === index || undefined}
                aria-label={`Go to slide ${i + 1}`}
                /* APG (grouped carousel): "the picker button representing the currently displayed
                   slide has the property aria-disabled set to true", and the pattern is explicit
                   that `aria-disabled` beats the HTML `disabled` attribute here because the button
                   must stay in the Tab sequence. So the current dot announces as unavailable while
                   remaining reachable — and it stays pressable, which is a no-op by construction
                   (`goTo(index)` is the slide already shown). This replaces `aria-current`, which
                   the pattern does not use for pickers. */
                aria-disabled={i === index || undefined}
                onPress={() => goTo(i)}
              >
                {/* A real element, not a pseudo: the dot needs THREE layers — the painted mark, the
                    hover/pressed state layer behind it, and the focus ring — and a button has only
                    two pseudo-elements. The mark takes the element so `::before` can be the state
                    layer (ADR-0009), matching Checkbox/Radio/Switch. Decorative; the button already
                    carries the accessible name. */}
                <span aria-hidden="true" className="sd-carousel__indicator" />
              </AriaButton>
            ))}
          </div>
        </>
      )}
    </section>
  );
}

/* Carousel.css — .sd-carousel (+ BEM sub-parts)
   sd- prefix / single flat classes / Cmp tokens only (focus-ring + motion are the
   sanctioned Sys carve-outs). Snap-scrolled track inside a scrolling viewport;
   prev/next Buttons overlaid in the viewport's own grid row; dots in the row below. */
/* A two-row GRID, not a positioned block. The arrows must centre on the SLIDE, and
   `position: absolute; inset-block-start: 50%` against this element resolves against a height that
   includes the dots row below the viewport, so both arrows would sit 18px low.

   Subtracting the dots' height in a `calc()` was rejected: it would encode one part's
   geometry into another part's rule, and break the moment the dots wrap or a consumer retunes
   `carousel.dot.gap`. Putting the arrows INSIDE the viewport was rejected too — it is a scroll
   container, so they would scroll away with the slides.

   The grid makes the relationship structural instead of arithmetic. Arrows and viewport share row 1,
   so `align-self: center` centres them on the slide by construction, and nothing here needs to know
   how tall the dots are. `position: relative` stays because the dots' own state layers are absolute
   within their buttons and consumers may anchor to the root. */
.sd-carousel {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto;
}

/* A real scroll container, not a transformed track. Paging is CSS Scroll Snap, so swipe,
   trackpad, wheel and keyboard paging all come from the browser instead of a hand-rolled
   gesture layer — and the inline axis flips under `dir="rtl"` on its own, which the old
   `transform: translateX(-N%)` could not: it is a PHYSICAL offset, so in RTL (where the flex
   row already runs right-to-left) it pushed the track the wrong way and the viewport rendered
   BLANK — measured, no slide covered even half the box.
   `overscroll-behavior-inline: contain` keeps a swipe that runs off the last slide from being
   taken by the browser as a back/forward page-navigation gesture (iOS Safari especially).
   The scrollbar is hidden because the prev/next Buttons and the dots are the affordance — a
   raw bar under every carousel would be chrome the component already provides. */
.sd-carousel__viewport {
  grid-area: 1 / 1;
  /* §6-3: the DS ring is drawn below, so the UA outline is reset on the BASE rule —
     inside the focus rule it lands too late and the OS accent paints alongside ours. */
  outline: none;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: inline mandatory;
  overscroll-behavior-inline: contain;
  scroll-behavior: smooth;
  border-radius: var(--sd-carousel-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  scrollbar-width: none;
}

.sd-carousel__viewport::-webkit-scrollbar {
  display: none;
}

/* The scrollport is a tab stop (see the tsx), so it needs the library's ring like any other
   focusable part — without it, keyboard paging would be invisible. */
.sd-carousel__viewport:focus-visible {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-carousel__track {
  display: flex;
}

.sd-carousel__slide {
  flex: 0 0 100%;
  min-width: 0;
  scroll-snap-align: start;
}

/* LAYOUT, not `transform`. These arrows ARE Buttons, and `.sd-button[data-pressed]` sets
   `transform: scale(var(--sd-state-pressed-scale))` — `transform` is a single property, so the
   more specific state rule (0,2,0 beats 0,1,0) REPLACED the centring rather than adding to it.
   A transform centring would go from `matrix(1,0,0,1,0,-16)` to `matrix(0.98,0,0,0.98,0,0)` on
   press, a 16px drop on a 32px button that Button's own `transition: transform` animates.
   Two remedies compose instead of colliding, and this file uses the SECOND: the independent
   `translate` property (which composes with `transform`), or taking the position out of the
   transform system entirely — `grid-area` + `align-self: center` below, which is what is here.
   `transform-translate:check` guards the other half, the same way the `[data-variant="outline"]` background rule
   below documents the specificity trap it shares. */
.sd-carousel__prev,
.sd-carousel__next {
  grid-area: 1 / 1;
  align-self: center;
  z-index: 1;
}

/* Opaque, because these sit ON the slide. `variant="outline"` (formerly named `secondary`) is a
   transparent + border button — `button/background/outline` is literally `transparent` — which is
   correct on a page surface but leaves the icon reading against whatever the slide happens to be:
   measured 2.4:1 on the story's own slide, under the 3:1 WCAG 1.4.11 floor for a UI component.
   The `[data-variant="outline"]` qualifier is load-bearing, not decoration: it is what the Button
   itself styles the transparent fill with, so a bare `.sd-carousel__prev` (0,1,0) LOSES to
   `.sd-button[data-variant="outline"]` (0,2,0) and the override silently does nothing — measured,
   the first attempt at this rule left the control at 1.18:1. Matching the attribute makes it (0,3,0),
   so it wins on specificity rather than on stylesheet order. Same element (the Button carries both
   classes), so this is still a same-element selector, not a descendant combinator. */
.sd-carousel__prev[data-variant="outline"],
.sd-carousel__next[data-variant="outline"],
.sd-carousel__step[data-variant="outline"] {
  background: var(--sd-carousel-control-background);
}

.sd-carousel__prev {
  justify-self: start;
  margin-inline-start: var(--sd-carousel-control-inset);
}

.sd-carousel__next {
  justify-self: end;
  margin-inline-end: var(--sd-carousel-control-inset);
}

/* The controls move to their logical edges automatically; mirror the directional glyph with them.
   The independent scale composes with Button's pressed-state transform. */
.sd-carousel__prev:dir(rtl),
.sd-carousel__next:dir(rtl),
.sd-carousel__step:dir(rtl) {
  scale: -1 1;
}

.sd-carousel__dots {
  grid-area: 2 / 1;
  display: flex;
  justify-content: center;
  gap: var(--sd-carousel-dot-gap);
  margin-block-start: var(--sd-carousel-gap);
}

/* The BUTTON is the pointer target (24, WCAG 2.5.8 — governed by docs/rules/accessibility.md); the visible
   mark is the 8px `__indicator` circle inside it. Sizing the button to the mark instead gave an 8×8
   target — a third of the minimum, and small enough that the spacing exception could not rescue it
   either (8px dots 4px apart put the 24px circles deep inside each other). Transparent, so only the
   indicator and the state layer show.
   The hover/pressed values are set HERE and read on the child (§6.5 `-current` local intermediate),
   because a combinator-free child cannot see its parent's state. */
.sd-carousel__dot {
  --sd-carousel-dot-state-layer-current: transparent;

  /* §6-3: the reset belongs on the BASE rule. On `[data-focus-visible]` it does the most damage: it
     kills the UA outline exactly when the outline is the only indicator left, since forced-colors
     mode drops the box-shadow ring below. */
  outline: none;

  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--sd-carousel-dot-touch-target-size);
  height: var(--sd-carousel-dot-touch-target-size);
  padding: 0;
  border: 0;
  border-radius: var(--sd-carousel-dot-radius);
  corner-shape: round;
  background: none;
  cursor: pointer;
}

/* Interaction state layer (ADR-0009) — a tinted disc BEHIND the mark, the same treatment
   Checkbox/Radio/Switch use. It replaces the old `transform: scale` on the mark: growing the dot
   made the indicator itself change size, which reads as the CONTENT changing rather than as a
   hover affordance, and it was the one interactive part in the library still outside the
   state-layer idiom. The layer is inset off the 24px button rather than spread off the 8px mark, so
   it lands on the pointer target exactly — nothing moves or resizes on hover. */
.sd-carousel__dot::before {
  content: "";
  position: absolute;
  inset: var(--sd-carousel-dot-state-layer-inset);
  border-radius: var(--sd-carousel-dot-radius);
  corner-shape: round;
  background: var(--sd-carousel-dot-state-layer-current);
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

/* Hover/press feedback off the RAC-emitted state attributes (contract §6.3) — the dot is a React
   Aria `Button`, so `useHover` already ignores the synthetic hover a tap emits and `usePress`
   already cancels a press that slides off the target. That is what retired the old
   `@media (hover: hover)` guard around `:hover`: the guard was compensating for native pseudo-
   classes, and the primitive does the same job properly (a touch never reports as hovered at all,
   rather than every touch device losing hover styling). */
.sd-carousel__dot[data-hovered] {
  --sd-carousel-dot-state-layer-current: var(--sd-state-hover);
}

.sd-carousel__dot[data-pressed] {
  --sd-carousel-dot-state-layer-current: var(--sd-state-pressed);
}

.sd-carousel__dot[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* Selected is set on the BUTTON but painted on the mark — same `-current` route as the state layer
   above, for the same combinator-free reason. */
.sd-carousel__dot[data-selected] {
  --sd-carousel-dot-background-current: var(--sd-carousel-dot-background-selected);
}

/* The painted mark. Above the state layer (which is `position: absolute` with no z-index, so a
   positioned sibling later in the DOM wins), and it never changes size — only its colour moves,
   between the resting and selected tokens. */
.sd-carousel__indicator {
  position: relative;
  width: var(--sd-carousel-dot-size);
  height: var(--sd-carousel-dot-size);
  border-radius: var(--sd-carousel-dot-radius);
  corner-shape: round;
  background: var(--sd-carousel-dot-background-current, var(--sd-carousel-dot-background));
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

/* Paging is now a scroll, so the slide animation is `scroll-behavior` rather than a
   transition — it is disabled here, in the same block as the rest. */
@media (prefers-reduced-motion: reduce) {
  .sd-carousel__viewport {
    scroll-behavior: auto;
  }

  .sd-carousel__dot::before,
  .sd-carousel__indicator {
    transition: none;
  }
}

/* indicator="counter": one row, the slide alone. The position label rides the start corner and the
   two controls the end corner, both on the slide's bottom edge, so a banner's content is never
   covered. The corners hold them off the edge by the controls' own inset. */
.sd-carousel[data-indicator="counter"] {
  grid-template-rows: auto;
}

.sd-carousel__counter {
  grid-area: 1 / 1;
  align-self: end;
  justify-self: start;
  margin: var(--sd-carousel-control-inset);
  z-index: 1;
}

.sd-carousel__controls {
  grid-area: 1 / 1;
  align-self: end;
  justify-self: end;
  display: flex;
  gap: var(--sd-carousel-control-gap);
  margin: var(--sd-carousel-control-inset);
  z-index: 1;
}

/* controlsFrom: the prev/next controls show only from a breakpoint step up, the ladder and the
   mobile-first order of `Show` (tokens/sys/breakpoint.json, literal because @media cannot read
   var()). The root sets a `-current` relay the controls read (§6.5), so no combinator reaches
   them. `visibility: hidden` takes a hidden control out of the tab order and the accessibility tree
   without restating Button's own `display`, and the controls are overlays on the slide's grid cell,
   so nothing reflows. Swipe, the focusable viewport and the indicator keep paging below the step. */
.sd-carousel[data-controls-from] {
  --sd-carousel-controls-visibility-current: hidden;
}

@media (min-width: 768px) {
  .sd-carousel[data-controls-from="medium"] {
    --sd-carousel-controls-visibility-current: visible;
  }
}

@media (min-width: 1024px) {
  .sd-carousel[data-controls-from="large"] {
    --sd-carousel-controls-visibility-current: visible;
  }
}

.sd-carousel__prev,
.sd-carousel__next,
.sd-carousel__controls {
  visibility: var(--sd-carousel-controls-visibility-current, visible);
}
